tasks.answer:
def guess_game(secret):
    lo, hi = 1, 100
    tries = 0
    asked = []
    while lo <= hi:
        mid = (lo + hi) // 2
        asked.append(mid)
        tries += 1
        if mid == secret:
            break
        elif mid < secret:
            lo = mid + 1
        else:
            hi = mid - 1
    print(f"{secret}: {' → '.join(map(str, asked))} ({tries}번)")

for s in (37, 1, 100):
    guess_game(s)
